-- Transición aditiva: ninguna aplicación consolidada se divide o reinterpreta.
ALTER TABLE nomina_borrador DROP CONSTRAINT nomina_borrador_estado_check;
ALTER TABLE nomina_borrador ALTER COLUMN estado TYPE VARCHAR(24);
ALTER TABLE nomina_borrador ADD CONSTRAINT nomina_borrador_estado_check CHECK(estado IN ('BORRADOR','CANCELADO','APLICADA','AUTORIZADA','PARCIALMENTE_PAGADA','PAGADA'));
ALTER TABLE movimiento_financiero DROP CONSTRAINT ck_movimiento_clase;
ALTER TABLE movimiento_financiero ADD CONSTRAINT ck_movimiento_clase CHECK(clase IN ('COBRO','OPERACION','TRASPASO','DEVOLUCION','AJUSTE','REVERSO','ANULACION','NOMINA','PRESTAMO','NOMINA_REVERSO'));
CREATE TABLE nomina_autorizacion (
 borrador_id BIGINT PRIMARY KEY, institucion_id BIGINT NOT NULL, periodo_id BIGINT NOT NULL, revision INTEGER NOT NULL,
 usuario_id BIGINT NOT NULL REFERENCES usuario(id), ocurrido_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 motivo VARCHAR(2000) NOT NULL CHECK(btrim(motivo)<>''),
 FOREIGN KEY(borrador_id,institucion_id,periodo_id) REFERENCES nomina_borrador(id,institucion_id,periodo_id),
 FOREIGN KEY(borrador_id,revision) REFERENCES nomina_borrador_revision(borrador_id,numero)
);
CREATE TABLE nomina_pago_intento (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 fila_id BIGINT NOT NULL REFERENCES nomina_borrador_empleado(id),
 institucion_id BIGINT NOT NULL REFERENCES institucion(id),
 solicitud UUID NOT NULL, estado VARCHAR(10) NOT NULL CHECK(estado IN ('PAGADO','RECHAZADO','REVERTIDO')),
 monto NUMERIC(19,2) NOT NULL CHECK(monto>0), moneda VARCHAR(3) NOT NULL,
 movimiento_id BIGINT UNIQUE REFERENCES movimiento_financiero(id),
 referencia VARCHAR(150) NOT NULL CHECK(btrim(referencia)<>''), motivo VARCHAR(2000) NOT NULL CHECK(btrim(motivo)<>''),
 usuario_id BIGINT NOT NULL REFERENCES usuario(id), ocurrido_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK((estado='RECHAZADO')=(movimiento_id IS NULL)), UNIQUE(institucion_id,solicitud)
);
CREATE UNIQUE INDEX ux_nomina_pago_vigente ON nomina_pago_intento(fila_id) WHERE estado='PAGADO';
CREATE INDEX ix_nomina_pago_fila ON nomina_pago_intento(fila_id,id);
CREATE TABLE nomina_pago_reversa (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, pago_id BIGINT NOT NULL UNIQUE REFERENCES nomina_pago_intento(id),
 institucion_id BIGINT NOT NULL REFERENCES institucion(id), movimiento_id BIGINT NOT NULL UNIQUE REFERENCES movimiento_financiero(id),
 referencia VARCHAR(150) NOT NULL CHECK(btrim(referencia)<>''), motivo VARCHAR(2000) NOT NULL CHECK(btrim(motivo)<>''),
 usuario_id BIGINT NOT NULL REFERENCES usuario(id), ocurrido_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE prestamo_abono_nomina (
 pago_id BIGINT NOT NULL REFERENCES nomina_pago_intento(id), prestamo_id BIGINT NOT NULL REFERENCES prestamo_empleado(id),
 importe NUMERIC(19,2) NOT NULL CHECK(importe>0), saldo_anterior NUMERIC(19,2) NOT NULL, saldo_posterior NUMERIC(19,2) NOT NULL,
 CHECK(saldo_anterior>=importe AND saldo_posterior=saldo_anterior-importe), PRIMARY KEY(pago_id,prestamo_id)
);
CREATE INDEX ix_prestamo_abono_saldo ON prestamo_abono_nomina(prestamo_id,pago_id);
CREATE TABLE prestamo_abono_compensacion (
 reversa_id BIGINT NOT NULL REFERENCES nomina_pago_reversa(id), pago_id BIGINT NOT NULL, prestamo_id BIGINT NOT NULL,
 importe NUMERIC(19,2) NOT NULL CHECK(importe>0), PRIMARY KEY(pago_id,prestamo_id),
 FOREIGN KEY(pago_id,prestamo_id) REFERENCES prestamo_abono_nomina(pago_id,prestamo_id)
);
CREATE VIEW prestamo_saldo AS
 SELECT p.id,p.institucion_id,p.empleado_id,coalesce(en.importe,0)-coalesce(a.abonado,0) saldo
 FROM prestamo_empleado p LEFT JOIN prestamo_entrega en ON en.prestamo_id=p.id
 LEFT JOIN LATERAL(SELECT sum(an.importe) abonado FROM prestamo_abono_nomina an JOIN nomina_pago_intento ni ON ni.id=an.pago_id
 WHERE an.prestamo_id=p.id AND ni.estado='PAGADO')a ON true;
ALTER TABLE prestamo_empleado DROP CONSTRAINT prestamo_empleado_estado_check;
ALTER TABLE prestamo_empleado ADD CONSTRAINT prestamo_empleado_estado_check CHECK(estado IN ('BORRADOR','ACTIVO','LIQUIDADO','CANCELADO'));
-- Las condiciones de un préstamo entregado siguen siendo inmutables.
ALTER FUNCTION proteger_prestamo_empleado() RENAME TO proteger_prestamo_empleado_v133;
CREATE FUNCTION proteger_prestamo_etapa5() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE deuda NUMERIC; BEGIN
 IF TG_OP='UPDATE' AND OLD.estado IN ('ACTIVO','LIQUIDADO') THEN
  SELECT saldo INTO deuda FROM prestamo_saldo WHERE id=OLD.id;
  IF NEW.estado NOT IN ('ACTIVO','LIQUIDADO') OR NEW.estado<>(CASE WHEN deuda=0 THEN 'LIQUIDADO' ELSE 'ACTIVO' END)
    OR deuda<0 OR NEW.version<>OLD.version+1 OR
    (to_jsonb(NEW)-ARRAY['estado','version','motivo_operacion','actualizado_por_id','actualizado_en']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['estado','version','motivo_operacion','actualizado_por_id','actualizado_en']) THEN
   RAISE EXCEPTION 'El estado debe corresponder al saldo real, sin cambiar condiciones';
  END IF;
  RETURN NEW;
 END IF;
 -- Se conserva íntegra la validación V133 para borradores y entregas.
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Conserva el préstamo y su historia'; END IF;
 IF OLD.estado<>'BORRADOR' OR NEW.version<>OLD.version+1 OR
 (NEW.id,NEW.institucion_id,NEW.empleado_id,NEW.solicitud,NEW.creado_por_id,NEW.creado_en) IS DISTINCT FROM
 (OLD.id,OLD.institucion_id,OLD.empleado_id,OLD.solicitud,OLD.creado_por_id,OLD.creado_en) THEN RAISE EXCEPTION 'Préstamo no modificable'; END IF;
 IF NEW.estado<>'BORRADOR' AND (to_jsonb(NEW)-ARRAY['estado','motivo_operacion','actualizado_por_id','actualizado_en','version']) IS DISTINCT FROM
 (to_jsonb(OLD)-ARRAY['estado','motivo_operacion','actualizado_por_id','actualizado_en','version']) THEN RAISE EXCEPTION 'Conserva condiciones originales'; END IF;
 IF NEW.estado='ACTIVO' AND NOT EXISTS(SELECT 1 FROM prestamo_entrega en JOIN movimiento_financiero m ON m.id=en.movimiento_id WHERE en.prestamo_id=OLD.id AND en.institucion_id=OLD.institucion_id AND en.empleado_id=OLD.empleado_id AND en.importe=OLD.importe AND en.moneda=OLD.moneda AND m.institucion_id=en.institucion_id AND m.clase='PRESTAMO' AND m.direccion='EGRESO' AND m.monto=en.importe) THEN RAISE EXCEPTION 'Entrega sin egreso coincidente'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER tr_prestamo_proteger ON prestamo_empleado;
CREATE TRIGGER tr_prestamo_proteger BEFORE UPDATE OR DELETE ON prestamo_empleado FOR EACH ROW EXECUTE FUNCTION proteger_prestamo_etapa5();
CREATE OR REPLACE FUNCTION proteger_nomina_borrador() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Conserva la nómina y sus revisiones'; END IF;
 IF TG_TABLE_NAME='nomina_borrador' THEN
  IF OLD.estado IN ('CANCELADO','APLICADA') OR (NEW.id,NEW.institucion_id,NEW.periodo_id,NEW.creado_por_id,NEW.creado_en) IS DISTINCT FROM (OLD.id,OLD.institucion_id,OLD.periodo_id,OLD.creado_por_id,OLD.creado_en) THEN RAISE EXCEPTION 'Nómina histórica inmutable'; END IF;
  IF OLD.estado IN ('AUTORIZADA','PARCIALMENTE_PAGADA','PAGADA') AND
   (to_jsonb(NEW)-ARRAY['estado','version','motivo_operacion','actualizado_por_id','actualizado_en']) IS DISTINCT FROM
   (to_jsonb(OLD)-ARRAY['estado','version','motivo_operacion','actualizado_por_id','actualizado_en']) THEN RAISE EXCEPTION 'La revisión autorizada no cambia'; END IF;
  IF NEW.estado IN ('AUTORIZADA','PARCIALMENTE_PAGADA','PAGADA') AND NOT EXISTS(SELECT 1 FROM nomina_autorizacion a WHERE a.borrador_id=NEW.id AND a.revision=NEW.revision_actual) THEN RAISE EXCEPTION 'Falta autorización de esta revisión'; END IF;
  IF NEW.estado IN ('AUTORIZADA','PARCIALMENTE_PAGADA','PAGADA') AND NEW.estado<>(SELECT CASE WHEN count(ni.id)=0 THEN 'AUTORIZADA' WHEN count(ni.id)=count(*) THEN 'PAGADA' ELSE 'PARCIALMENTE_PAGADA' END FROM nomina_borrador_empleado ne LEFT JOIN nomina_pago_intento ni ON ni.fila_id=ne.id AND ni.estado='PAGADO' WHERE ne.borrador_id=NEW.id AND ne.revision=NEW.revision_actual) THEN RAISE EXCEPTION 'Estado no coincide con pagos individuales vigentes'; END IF;
  IF OLD.estado<>'BORRADOR' AND NEW.estado NOT IN ('AUTORIZADA','PARCIALMENTE_PAGADA','PAGADA') THEN RAISE EXCEPTION 'No se cancela una nómina autorizada como borrador'; END IF;
 ELSIF TG_TABLE_NAME='nomina_borrador_empleado' THEN
  IF EXISTS(SELECT 1 FROM nomina_borrador WHERE id=OLD.borrador_id AND estado<>'BORRADOR') OR NOT OLD.activo OR NEW.activo OR (to_jsonb(NEW)-'activo') IS DISTINCT FROM (to_jsonb(OLD)-'activo') THEN RAISE EXCEPTION 'Fotografía histórica inmutable'; END IF;
 ELSE RAISE EXCEPTION 'La revisión histórica no cambia'; END IF;
 RETURN NEW;
END $$;
CREATE FUNCTION proteger_intento_nomina() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Conserva los intentos de pago'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.estado<>'PAGADO' OR NEW.estado<>'REVERTIDO' OR (to_jsonb(NEW)-'estado') IS DISTINCT FROM (to_jsonb(OLD)-'estado') OR NOT EXISTS(SELECT 1 FROM nomina_pago_reversa WHERE pago_id=OLD.id) THEN RAISE EXCEPTION 'Sólo reversa trazable del pago'; END IF;
 ELSE
  IF NEW.estado='REVERTIDO' OR NOT EXISTS(SELECT 1 FROM nomina_borrador_empleado ne JOIN nomina_autorizacion a ON a.borrador_id=ne.borrador_id AND a.revision=ne.revision WHERE ne.id=NEW.fila_id AND ne.institucion_id=NEW.institucion_id AND ne.propuesto=NEW.monto AND ne.moneda=NEW.moneda) THEN RAISE EXCEPTION 'Pago no corresponde a revisión autorizada'; END IF;
  IF NEW.estado='PAGADO' AND NOT EXISTS(SELECT 1 FROM movimiento_financiero m WHERE m.id=NEW.movimiento_id AND m.institucion_id=NEW.institucion_id AND m.clase='NOMINA' AND m.direccion='EGRESO' AND m.monto=NEW.monto AND m.clave_idempotencia='NOMINA-EMP:'||NEW.id) THEN RAISE EXCEPTION 'Falta egreso único del pago individual'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER tr_nomina_intento BEFORE INSERT OR UPDATE OR DELETE ON nomina_pago_intento FOR EACH ROW EXECUTE FUNCTION proteger_intento_nomina();
CREATE TRIGGER tr_nomina_autorizacion_inmutable BEFORE UPDATE OR DELETE ON nomina_autorizacion FOR EACH ROW EXECUTE FUNCTION proteger_personal_historial();
CREATE TRIGGER tr_nomina_reversa_inmutable BEFORE UPDATE OR DELETE ON nomina_pago_reversa FOR EACH ROW EXECUTE FUNCTION proteger_personal_historial();
CREATE TRIGGER tr_prestamo_abono_inmutable BEFORE UPDATE OR DELETE ON prestamo_abono_nomina FOR EACH ROW EXECUTE FUNCTION proteger_personal_historial();
CREATE TRIGGER tr_prestamo_compensacion_inmutable BEFORE UPDATE OR DELETE ON prestamo_abono_compensacion FOR EACH ROW EXECUTE FUNCTION proteger_personal_historial();
CREATE FUNCTION validar_reversa_nomina() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM nomina_pago_intento ni JOIN movimiento_financiero m ON m.id=NEW.movimiento_id WHERE ni.id=NEW.pago_id AND ni.estado='PAGADO' AND ni.institucion_id=NEW.institucion_id AND m.institucion_id=ni.institucion_id AND m.clase='NOMINA_REVERSO' AND m.direccion='INGRESO' AND m.monto=ni.monto AND m.reversa_de_id=ni.movimiento_id) THEN RAISE EXCEPTION 'Compensación no corresponde al pago individual vigente'; END IF;RETURN NEW;
END $$;
CREATE TRIGGER tr_reversa_nomina_validar BEFORE INSERT ON nomina_pago_reversa FOR EACH ROW EXECUTE FUNCTION validar_reversa_nomina();
-- Congelar ocasionales al autorizar, no sólo en la aplicación consolidada antigua.
CREATE FUNCTION validar_autorizacion_nomina() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM nomina_borrador b WHERE b.id=NEW.borrador_id AND b.institucion_id=NEW.institucion_id AND b.estado='BORRADOR' AND b.revision_actual=NEW.revision)
 OR NOT EXISTS(SELECT 1 FROM nomina_borrador_empleado ne WHERE ne.borrador_id=NEW.borrador_id AND ne.revision=NEW.revision)
 OR EXISTS(SELECT 1 FROM nomina_borrador_empleado ne WHERE ne.borrador_id=NEW.borrador_id AND ne.revision=NEW.revision AND ne.propuesto<=0)
 THEN RAISE EXCEPTION 'Autoriza una revisión vigente con empleados e importes positivos'; END IF;RETURN NEW;
END $$;
CREATE TRIGGER tr_autorizacion_validar BEFORE INSERT ON nomina_autorizacion FOR EACH ROW EXECUTE FUNCTION validar_autorizacion_nomina();
CREATE FUNCTION impedir_insertar_empleado_autorizado() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM nomina_borrador WHERE id=NEW.borrador_id AND estado<>'BORRADOR') THEN RAISE EXCEPTION 'No agregar empleados a una nómina congelada'; END IF;RETURN NEW;
END $$;
CREATE TRIGGER tr_nomina_empleado_insertar BEFORE INSERT ON nomina_borrador_empleado FOR EACH ROW EXECUTE FUNCTION impedir_insertar_empleado_autorizado();
CREATE FUNCTION validar_abono_nomina() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM nomina_pago_intento ni JOIN nomina_borrador_empleado ne ON ne.id=ni.fila_id
 JOIN prestamo_empleado p ON p.id=NEW.prestamo_id AND p.institucion_id=ne.institucion_id AND p.empleado_id=ne.empleado_id
 JOIN prestamo_saldo s ON s.id=p.id
 CROSS JOIN LATERAL jsonb_array_elements(ne.fuentes->'prestamos') x
 WHERE ni.id=NEW.pago_id AND ni.estado='PAGADO' AND (x->>'id')::bigint=p.id AND (x->>'cuota')::numeric=NEW.importe AND s.saldo=NEW.saldo_anterior AND s.saldo>=NEW.importe)
 THEN RAISE EXCEPTION 'Abono no corresponde al pago, cuota autorizada o saldo real'; END IF;RETURN NEW;
END $$;
CREATE TRIGGER tr_abono_validar BEFORE INSERT ON prestamo_abono_nomina FOR EACH ROW EXECUTE FUNCTION validar_abono_nomina();
CREATE FUNCTION proteger_ocasional_autorizado() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM nomina_autorizacion a JOIN nomina_borrador_empleado ne ON ne.borrador_id=a.borrador_id AND ne.revision=a.revision WHERE ne.empleado_id=OLD.empleado_id AND ne.fuentes->'ocasionales' @> jsonb_build_array(jsonb_build_object('id',OLD.id))) THEN RAISE EXCEPTION 'Concepto incluido en nómina autorizada; conserva su historia'; END IF;RETURN NEW;
END $$;
CREATE TRIGGER tr_ocasional_autorizado BEFORE UPDATE ON concepto_empleado_periodo FOR EACH ROW EXECUTE FUNCTION proteger_ocasional_autorizado();
